<?php
function packaging_ready(){return setting('packaging_version','')==='5.3.3';}
function packaging_require(){if(!packaging_ready())throw new Exception('Run the RAW / Repackaging upgrade first.');}
function packaging_condition($condition){return in_array(norm($condition),['raw / for packaging','raw','for packaging','for repackaging','for repack'],true);}
function packaging_kind($condition){if(packaging_condition($condition))return 'packaging';if(in_array(norm($condition),['damage','damaged','damage / leak','damaged / leak','leaked','leak'],true))return 'damaged';return 'other';}
function migrate_packaging(){
 if(!complete_update_ready())throw new Exception('Install and run the V5.3 complete update first.');
 global $CFG;$cols=['non_sellable'=>['packaging_owner_id'=>'INT NULL','packaging_due_date'=>'DATE NULL','packaging_state'=>'VARCHAR(30) NULL','packaging_source'=>'VARCHAR(180) NULL','packaging_receipt_key'=>'CHAR(64) NULL'],'posted_returns'=>['repackaging_qty'=>'INT NOT NULL DEFAULT 0'],'borrowed_events'=>['repackaging_qty'=>'INT NOT NULL DEFAULT 0']];
 foreach($cols as $table=>$fields)foreach($fields as $name=>$definition){$q=db()->prepare('SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=? AND TABLE_NAME=? AND COLUMN_NAME=?');$q->execute([$CFG['db_name'],$table,$name]);if(!$q->fetchColumn())db()->exec("ALTER TABLE `$table` ADD COLUMN `$name` $definition");}
 if(!db()->query("SHOW INDEX FROM non_sellable WHERE Key_name='packaging_receipt_key'")->fetch())db()->exec('ALTER TABLE non_sellable ADD UNIQUE INDEX packaging_receipt_key(packaging_receipt_key)');
 db()->exec("CREATE TABLE IF NOT EXISTS packaging_completions(id BIGINT AUTO_INCREMENT PRIMARY KEY,completion_ref VARCHAR(100) NOT NULL UNIQUE,source_id BIGINT NOT NULL,product_id INT NOT NULL,qty INT NOT NULL,txn_date DATE NOT NULL,inflow_id BIGINT NOT NULL,release_id BIGINT NOT NULL,allocation_json LONGTEXT NOT NULL,reason TEXT NOT NULL,user_id INT NOT NULL,reversed_by_request BIGINT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(source_id)) ENGINE=InnoDB");
 set_setting('packaging_version','5.3.3');
}
function packaging_initialize($id){packaging_require();db()->prepare("UPDATE non_sellable SET packaging_owner_id=COALESCE(packaging_owner_id,?),packaging_state=COALESCE(packaging_state,'Pending') WHERE id=?")->execute([current_user()['id'],$id]);}
function packaging_source($id,$lock=false){$q=db()->prepare('SELECT n.*,p.name,p.master_sku FROM non_sellable n JOIN products p ON p.id=n.product_id WHERE n.id=?'.($lock?' FOR UPDATE':''));$q->execute([$id]);$r=$q->fetch();if(!$r||!packaging_condition($r['condition_type'])||$r['reversed_by_request']!==null||(int)$r['qty']<=0)throw new Exception('Select an active RAW / For Packaging source record.');$r['remaining']=max(0,(int)$r['qty']-release_total($id));return $r;}
function packaging_owner($id){$q=db()->prepare("SELECT role FROM users WHERE id=? AND active=1 AND approval_status='Approved'");$q->execute([(int)$id]);$ownerRole=$q->fetchColumn();if(!$ownerRole||!can_role_action($ownerRole,'import_orders'))throw new Exception('Select an active operational owner.');return (int)$id;}
function packaging_due($value,$start){$value=trim((string)$value);if($value==='')return null;$d=DateTime::createFromFormat('!Y-m-d',$value);if(!$d||$d->format('Y-m-d')!==$value||$value<$start)throw new Exception('Target completion date must be valid and not precede receipt date.');return $value;}
function packaging_receive_raw($input){
 packaging_require();if(!can_action('packaging_receive_raw'))throw new Exception('Inventory receiving access required.');
 return process_transaction(function()use($input){$pid=whole_number($input['product_id']??'','Product',1);active_product($pid);$qty=whole_number($input['qty']??'','RAW quantity',1);$date=process_date($input['txn_date']??'');require_open_inventory_date($date);$source=trim($input['supplier']??'');$ref=trim($input['reference_no']??'');if($source===''||strlen($source)>180||$ref===''||strlen($ref)>100)throw new Exception('Supplier/source and receipt reference are required.');$owner=packaging_owner($input['owner_id']??0);$due=packaging_due($input['due_date']??'',$date);$reason=process_reason($input['reason']??'');$key=hash('sha256',json_encode([norm($source),norm($ref),$pid]));
 db()->prepare('SELECT id FROM products WHERE id=? FOR UPDATE')->execute([$pid]);$q=db()->prepare('SELECT id FROM non_sellable WHERE packaging_receipt_key=? FOR UPDATE');$q->execute([$key]);if($q->fetchColumn())throw new Exception('This RAW receipt/product/source is already recorded. Review the original record.');
 db()->prepare("INSERT INTO non_sellable(txn_date,platform,order_id,product_id,qty,condition_type,action_type,status,origin,sellable_deducted,remarks,user_id,packaging_owner_id,packaging_due_date,packaging_state,packaging_source,packaging_receipt_key) VALUES(?,NULL,?,?,?,'RAW / For Packaging','For Packaging','Pending','RAW Receipt',0,?,?,?,?, 'Pending',?,?)")->execute([$date,$ref,$pid,$qty,$reason,current_user()['id'],$owner,$due,$source,$key]);$id=(int)db()->lastInsertId();audit('Receive RAW for packaging','Packaging','NS-'.$id,$qty.' pcs; physical and restricted stock increased; sellable unchanged; '.$source.'; '.$ref);return $id;});
}
function packaging_update($input){packaging_require();if(!can_action('packaging_update'))throw new Exception('Inventory controller access required.');return process_transaction(function()use($input){$r=packaging_source((int)($input['source_id']??0),true);if(!$r['remaining'])throw new Exception('No packaging quantity remains.');$state=$input['packaging_state']??'';if(!in_array($state,['Pending','In Progress','For Inspection'],true))throw new Exception('Use Ready for Sale with inspection and allocation approval to release stock.');$owner=packaging_owner($input['owner_id']??0);$due=packaging_due($input['due_date']??'',$r['txn_date']);$reason=process_reason($input['reason']??'');db()->prepare('UPDATE non_sellable SET packaging_state=?,packaging_owner_id=?,packaging_due_date=? WHERE id=?')->execute([$state,$owner,$due,$r['id']]);audit('Update packaging responsibility','Packaging','NS-'.$r['id'],$state.'; owner '.$owner.'; target '.($due??'not set').'; '.$reason);});}
function packaging_signature($id){$r=packaging_source($id);$s=stock_row($r['product_id']);return hash('sha256',json_encode([$r,$s['current'],$s['nonsellable'],platform_qty('Shopee',$r['product_id']),platform_qty('Lazada',$r['product_id']),platform_qty('TikTok',$r['product_id'])]));}
function packaging_complete($input){
 packaging_require();if(current_user()['role']!=='Admin')throw new Exception('Admin inspection approval is required for Ready for Sale.');if(empty($input['inspection_ack']))throw new Exception('Confirm the inspection and readiness for sale.');
 return process_transaction(function()use($input){$id=(int)($input['source_id']??0);$r=packaging_source($id,true);$pid=(int)$r['product_id'];db()->prepare('SELECT id FROM products WHERE id=? AND active=1 FOR UPDATE')->execute([$pid]);active_product($pid);$date=process_date($input['txn_date']??'');require_open_inventory_date($date);if($date<$r['txn_date'])throw new Exception('Completion cannot precede receipt date.');$qty=whole_number($input['qty']??'','Ready quantity',1);$reason=process_reason($input['reason']??'');$ref=trim($input['completion_ref']??'');if(!preg_match('/^[A-Za-z0-9_-]{6,100}$/D',$ref))throw new Exception('Invalid completion reference. Refresh the form.');$prior=db()->prepare('SELECT id FROM packaging_completions WHERE completion_ref=? FOR UPDATE');$prior->execute([$ref]);if($prior->fetchColumn())throw new Exception('This Ready for Sale confirmation is already posted.');if(!hash_equals(packaging_signature($id),(string)($input['signature']??'')))throw new Exception('Source or stock quantities changed. Refresh the review before confirming.');
 check_platform_alignment($pid);$before=stock_row($pid);if($qty>$r['remaining']||$qty>$before['nonsellable'])throw new Exception('Ready quantity exceeds remaining source or Non-Sellable stock.');$allocation=[];foreach(['Shopee','Lazada','TikTok'] as $platform)$allocation[$platform]=whole_number($input['allocation'][$platform]??'','Allocation for '.$platform,0);if(array_sum($allocation)!==$qty)throw new Exception('Platform allocations must exactly equal the Ready for Sale quantity.');
 db()->prepare('INSERT INTO nonsellable_outflows(txn_date,product_id,qty,type,reference_no,remarks,user_id) VALUES(?,?,?,?,?,?,?)')->execute([$date,$pid,$qty,'Ready for Sale',$ref,$reason,current_user()['id']]);$release=(int)db()->lastInsertId();db()->prepare('INSERT INTO nonsellable_release_links(release_id,non_sellable_id,qty) VALUES(?,?,?)')->execute([$release,$id,$qty]);
 db()->prepare('INSERT INTO inflows(txn_date,reference_no,source_name,product_id,source_qty,source_uom,qty,type,remarks,user_id) VALUES(?,?,?,?,?,?,?,?,?,?)')->execute([$date,$ref,'NS-'.$id,$pid,$qty,'pc',$qty,'Ready for Sale',$reason,current_user()['id']]);$inflow=(int)db()->lastInsertId();foreach($allocation as $platform=>$q)if($q)change_platform_stock($platform,$pid,$q,$ref,$date);
 db()->prepare('INSERT INTO packaging_completions(completion_ref,source_id,product_id,qty,txn_date,inflow_id,release_id,allocation_json,reason,user_id) VALUES(?,?,?,?,?,?,?,?,?,?)')->execute([$ref,$id,$pid,$qty,$date,$inflow,$release,json_encode($allocation),$reason,current_user()['id']]);$completion=(int)db()->lastInsertId();db()->prepare('UPDATE non_sellable SET packaging_state=? WHERE id=?')->execute([$qty===$r['remaining']?'Completed':($r['packaging_state']??'For Inspection'),$id]);check_platform_alignment($pid);$after=stock_row($pid);if($after['physical']!==$before['physical'])throw new Exception('Physical inventory changed unexpectedly; completion rolled back.');audit('Approve Ready for Sale','Packaging','PC-'.$completion,$qty.' pcs on the same SKU; sellable '.$before['current'].' -> '.$after['current'].'; Non-Sellable '.$before['nonsellable'].' -> '.$after['nonsellable'].'; physical unchanged; '.$ref);return $completion;
 });
}
function packaging_attention($overdue=false){if(!packaging_ready())return 0;$sql="SELECT COUNT(*) FROM non_sellable n WHERE n.qty>0 AND n.reversed_by_request IS NULL AND LOWER(n.condition_type) IN ('raw / for packaging','raw','for packaging','for repackaging','for repack') AND n.qty>COALESCE((SELECT SUM(l.qty) FROM nonsellable_release_links l WHERE l.non_sellable_id=n.id),0)";if($overdue)$sql.=' AND n.packaging_due_date<CURDATE()';return (int)db()->query($sql)->fetchColumn();}
function packaging_reversal_plan($id,$plan){packaging_require();$q=db()->prepare('SELECT * FROM packaging_completions WHERE id=? AND reversed_by_request IS NULL');$q->execute([$id]);$c=$q->fetch();if(!$c)throw new Exception('Packaging completion already reversed or not found.');$q=db()->prepare('SELECT * FROM inflows WHERE id=? AND reversed_by_request IS NULL');$q->execute([$c['inflow_id']]);$plan['inflows']=$q->fetchAll();$q=db()->prepare('SELECT * FROM nonsellable_outflows WHERE id=? AND reversed_by_request IS NULL');$q->execute([$c['release_id']]);$plan['nonsellable_outflows']=$q->fetchAll();if(!$plan['inflows']||!$plan['nonsellable_outflows'])throw new Exception('Linked completion records changed.');$q=db()->prepare('SELECT * FROM nonsellable_release_links WHERE release_id=?');$q->execute([$c['release_id']]);$plan['release_links']=$q->fetchAll();$plan['completion']=$c;foreach(json_decode($c['allocation_json'],true) as $platform=>$qty)if($qty)$plan['platforms'][]=['pid'=>$c['product_id'],'platform'=>$platform,'delta'=>-$qty];$plan['reference']=$c['completion_ref'];return $plan;}
